    85	static inline void convertGfxColor(SplashColorPtr dest,
    86	                                   const SplashColorMode colorMode,
    87	                                   const GfxColorSpace *colorSpace,
    88	                                   const GfxColor *src) {
    89	  SplashColor color;
    90	  GfxGray gray;
    91	  GfxRGB rgb;
    92	  GfxCMYK cmyk;
    93	  GfxColor deviceN;
    94	
    95	  // make gcc happy
    96	  color[0] = color[1] = color[2] = 0;
    97	  color[3] = 0;
    98	  switch (colorMode) {
    99	    case splashModeMono1:
   100	    case splashModeMono8:
   101	      colorSpace->getGray(src, &gray);
   102	      color[0] = colToByte(gray);
   103	    break;
   104	    case splashModeXBGR8:
   105	      color[3] = 255;
   106	      // fallthrough
   107	    case splashModeBGR8:
   108	    case splashModeRGB8:
   109	      colorSpace->getRGB(src, &rgb);
   110	      color[0] = colToByte(rgb.r);
   111	      color[1] = colToByte(rgb.g);
   112	      color[2] = colToByte(rgb.b);
   113	    break;
   114	    case splashModeCMYK8:
   115	      colorSpace->getCMYK(src, &cmyk);
   116	      color[0] = colToByte(cmyk.c);
   117	      color[1] = colToByte(cmyk.m);
   118	      color[2] = colToByte(cmyk.y);
   119	      color[3] = colToByte(cmyk.k);
   120	    break;
   121	    case splashModeDeviceN8:
   122	      colorSpace->getDeviceN(src, &deviceN);
   123	      for (int i = 0; i < SPOT_NCOMPS + 4; i++)
   124	        color[i] = colToByte(deviceN.c[i]);
   125	    break;
   126	  }
   127	  splashColorCopy(dest, color);
   128	}
