   137	static inline void convertGfxShortColor(SplashColorPtr dest,
   138	                                   const SplashColorMode colorMode,
   139	                                   const GfxColorSpace *colorSpace,
   140	                                   const GfxColor *src) {
   141	  switch (colorMode) {
   142	    case splashModeMono1:
   143	    case splashModeMono8:
   144	    {
   145	      GfxGray gray;
   146	      colorSpace->getGray(src, &gray);
   147	      dest[0] = colToByte(gray);
   148	    }
   149	    break;
   150	    case splashModeXBGR8:
   151	      dest[3] = 255;
   152	      // fallthrough
   153	    case splashModeBGR8:
   154	    case splashModeRGB8:
   155	    {
   156	      GfxRGB rgb;
   157	      colorSpace->getRGB(src, &rgb);
   158	      dest[0] = colToByte(rgb.r);
   159	      dest[1] = colToByte(rgb.g);
   160	      dest[2] = colToByte(rgb.b);
   161	    }
   162	    break;
   163	    case splashModeCMYK8:
   164	    {
   165	      GfxCMYK cmyk;
   166	      colorSpace->getCMYK(src, &cmyk);
   167	      dest[0] = colToByte(cmyk.c);
   168	      dest[1] = colToByte(cmyk.m);
   169	      dest[2] = colToByte(cmyk.y);
   170	      dest[3] = colToByte(cmyk.k);
   171	    }
   172	    break;
   173	    case splashModeDeviceN8:
   174	    {
   175	      GfxColor deviceN;
   176	      colorSpace->getDeviceN(src, &deviceN);
   177	      for (int i = 0; i < SPOT_NCOMPS + 4; i++)
   178	        dest[i] = colToByte(deviceN.c[i]);
   179	    }
   180	    break;
   181	  }
