   229	SplashFunctionPattern::SplashFunctionPattern(SplashColorMode colorModeA, GfxState *stateA, GfxFunctionShading *shadingA)
   230	{
   231	  Matrix ctm;
   232	  SplashColor defaultColor;
   233	  GfxColor srcColor;
   234	  const double *matrix = shadingA->getMatrix();
   235	
   236	  shading = shadingA;
   237	  state = stateA;
   238	  colorMode = colorModeA;
   239	
   240	  state->getCTM(&ctm);
   241	
   242	  double a1 = ctm.m[0];
   243	  double b1 = ctm.m[1];
   244	  double c1 = ctm.m[2];
   245	  double d1 = ctm.m[3];
   246	
   247	  ctm.m[0] = matrix[0] * a1 + matrix[1] * c1;
   248	  ctm.m[1] = matrix[0] * b1 + matrix[1] * d1;
   249	  ctm.m[2] = matrix[2] * a1 + matrix[3] * c1;
   250	  ctm.m[3] = matrix[2] * b1 + matrix[3] * d1;
   251	  ctm.m[4] = matrix[4] * a1 + matrix[5] * c1 + ctm.m[4];
   252	  ctm.m[5] = matrix[4] * b1 + matrix[5] * d1 + ctm.m[5];
   253	  ctm.invertTo(&ictm);
   254	
   255	  gfxMode = shadingA->getColorSpace()->getMode();
   256	  shadingA->getColorSpace()->getDefaultColor(&srcColor);
   257	  shadingA->getDomain(&xMin, &yMin, &xMax, &yMax);
   258	  convertGfxColor(defaultColor, colorModeA, shadingA->getColorSpace(), &srcColor);
